const SWANS=[];
function valkenland(){const V=WD.valkenland;if(!V)return;const LK=V.LK,wood=MAT.wood||new T.MeshStandardMaterial({color:0x7a5434}),stone=MAT.stone||new T.MeshStandardMaterial({color:0x8a857a}),b=Bag();
  /* reeds round the lake */{const g=new T.ConeGeometry(.05,1.6,4);g.translate(0,.8,0);const brown=new T.MeshStandardMaterial({color:0x6a7a3a,roughness:.95}),N=420,im=new T.InstancedMesh(g,brown,N),m=new T.Matrix4(),q=new T.Quaternion(),e=new T.Euler(),v=new T.Vector3(),s=new T.Vector3();let k=0;for(let i=0;i<N*3&&k<N;i++){const a=Math.random()*6.283,r=LK.r+R(-14,6),x=LK.x+Math.cos(a)*r,z=LK.z+Math.sin(a)*r,h=terrainH(x,z);if(h>1.2||h<-1.8)continue;e.set(rr(.12),Math.random()*6,rr(.12));q.setFromEuler(e);s.set(1,R(.8,1.5),1);v.set(x,h,z);m.compose(v,q,s);im.setMatrixAt(k++,m)}im.count=k;im.instanceMatrix.needsUpdate=true;im.frustumCulled=false;scene.add(im)}
  /* swans */{const W=new T.MeshStandardMaterial({color:0xf4f4f0,roughness:.6}),O=new T.MeshStandardMaterial({color:0xe08a2a}),D=new T.MeshBasicMaterial({color:0x111111});for(let i=0;i<4;i++){const g=new T.Group();g.userData.dyn=true;const body=new T.Mesh(new T.SphereGeometry(.42,10,8),W);body.scale.set(.75,.62,1.3);body.position.y=.2;g.add(body);const tail=new T.Mesh(new T.ConeGeometry(.16,.4,6),W);tail.position.set(0,.34,-.58);tail.rotation.x=-1.1;g.add(tail);const neck=new T.Mesh(new T.CylinderGeometry(.06,.09,.8,6),W);neck.position.set(0,.68,.42);neck.rotation.x=.25;g.add(neck);const head=new T.Mesh(new T.SphereGeometry(.12,8,6),W);head.position.set(0,1.08,.52);g.add(head);const beak=new T.Mesh(new T.ConeGeometry(.05,.18,5),O);beak.position.set(0,1.05,.68);beak.rotation.x=1.5;g.add(beak);for(const sx of[-1,1]){const eye=new T.Mesh(new T.SphereGeometry(.02,4,3),D);eye.position.set(sx*.09,1.11,.56);g.add(eye)}scene.add(g);SWANS.push({g,a:Math.random()*6.283,r:40+i*14,sp:(i%2?1:-1)*(.035+Math.random()*.02),ph:Math.random()*6})}}
  /* Meeuwenklif: rowing boats on the beach, nets drying on poles */{const s=SITE.meeuwenklif,boatM=new T.MeshStandardMaterial({color:0x7a4a2a,roughness:.85}),inner=new T.MeshStandardMaterial({color:0x4a2e18}),boat=(x,z,ry,tilt)=>{const y=Math.max(terrainH(x,z),.1);b.add(new T.CylinderGeometry(.85,.5,3.8,8,1),boatM,x,y+.38,z,ry,Math.PI/2,0,1,1,.62);b.box(1.1,.08,2.5,inner,x,y+.62,z,ry);b.box(1.2,.08,.28,wood,x,y+.68,z,ry);b.box(.08,.08,2.6,wood,x+.5*Math.cos(ry),y+.75,z-.5*Math.sin(ry),ry,0,tilt)};boat(s.x-12,s.z+18,.4,.2);boat(s.x-17,s.z+15,-.5,-.2);boat(s.x+13,s.z+19,1.1,.15);
    const net=new T.MeshStandardMaterial({color:0x8a7a5a,transparent:true,opacity:.55,side:T.DoubleSide,roughness:1});for(const [dx,dz] of[[-20,4],[20,6]]){const x=s.x+dx,z=s.z+dz,y=terrainH(x,z);for(const k of[-2.2,2.2]){b.cyl(.08,.1,2.6,wood,x+k,y+1.3,z,6);addCircle(x+k,z,.15)}b.add(new T.PlaneGeometry(4.2,1.7),net,x,y+1.5,z);for(let i=0;i<7;i++)b.box(.02,1.7,.02,IRON,x-2+i*.66,y+1.5,z+.01);for(let i=0;i<4;i++)b.box(4.2,.02,.02,IRON,x,y+.8+i*.47,z+.01);b.box(4.6,.06,.06,wood,x,y+2.4,z)}}
  /* Oud-Valkenburg: an old graveyard */{const s=SITE.oudvalkenburg,gx=s.x+6,gz=s.z+22,y0=terrainH(gx,gz);const moss=new T.MeshStandardMaterial({color:0x6a7060,roughness:1});for(let r=0;r<3;r++)for(let c=0;c<4;c++){const x=gx-8+c*5.2+rr(.5),z=gz-4+r*4+rr(.4),y=terrainH(x,z),t=rr(.14);if(Math.random()<.75){b.box(1,1.1,.22,Math.random()<.5?stone:moss,x,y+.5,z,rr(.15),t);b.add(new T.CylinderGeometry(.5,.5,.22,10,1,false,0,Math.PI),moss,x,y+1.05,z,0,Math.PI/2,0)}else{b.box(.14,1.5,.14,wood,x,y+.75,z,0,t);b.box(.8,.12,.12,wood,x,y+1.1,z,0,t)}b.box(1.1,.08,2,moss,x,y+.05,z+1.2);addCircle(x,z,.4)}
    for(let i=0;i<=8;i++)for(const sz of[-1,1])b.box(.12,1.3,.12,IRON,gx-10+i*2.5,y0+.65,gz+3+sz*7);b.box(20,.08,.08,IRON,gx,y0+1.2,gz-4);b.box(20,.08,.08,IRON,gx,y0+1.2,gz+10);b.add(new T.ConeGeometry(.08,.3,5),IRON,gx-10,y0+1.4,gz-4)}
  /* Noordertand: rails and a mine cart full of ore */{const s=SITE.noordertand,z0=s.z-10,oreM=new T.MeshStandardMaterial({color:0xc07a3a,emissive:0x3a1a08,roughness:.6});for(let i=0;i<20;i++){const z=z0+i*1.4,y=terrainH(s.x,z);b.box(1.6,.1,.3,wood,s.x,y+.06,z);for(const sx of[-1,1])b.box(.1,.1,1.5,IRON,s.x+sx*.55,y+.15,z)}const cz=z0+10,cy=terrainH(s.x,cz)+.2;b.box(1.5,.9,2.2,wood,s.x,cy+.75,cz);for(const [dx,dz] of[[-.72,-.8],[.72,-.8],[-.72,.8],[.72,.8]])b.cyl(.28,.28,.12,IRON,s.x+dx,cy+.2,cz+dz,10,0,Math.PI/2);for(let i=0;i<7;i++)b.add(new T.DodecahedronGeometry(.32,0),oreM,s.x+rr(.5),cy+1.3+rr(.1),cz+rr(.8));addCircle(s.x,cz,1)}
  b.build()}
const _bfP=buildFantasy;buildFantasy=function(){_bfP();const t0=performance.now();let RS=[],T0=[];try{RS=roadSamples();T0=townsOf()}catch(e){console.warn('plaatsen',e)}
  for(const [n,f] of[['borden',()=>signs(RS)],['lantaarns',()=>lanterns(RS,T0)],['vlaggetjes',()=>bunting(T0)],['valkenland',valkenland]])try{const r=f();if(r!==undefined)console.log('plaatsen '+n+': '+r)}catch(e){console.warn('plaatsen '+n,e)}console.log('plaatsen klaar in '+Math.round(performance.now()-t0)+' ms')};
/* lanterns light up at dusk; swans swim */
ANIMS.push(dt=>{dt=typeof dt==='number'?dt:.016;const n=ENV.night||0;LAMP.emissiveIntensity=n>.15?Math.min(1.4,n*2):0;const V=WD.valkenland;if(!V||!SWANS.length||Math.hypot(PL.x-V.LK.x,PL.z-V.LK.z)>360)return;const t=performance.now()*.001;for(const q of SWANS){q.a+=q.sp*dt;const x=V.LK.x+Math.cos(q.a)*q.r,z=V.LK.z+Math.sin(q.a)*q.r*.86;q.g.position.set(x,.02+Math.sin(t*1.2+q.ph)*.03,z);q.g.rotation.y=Math.atan2(-Math.sin(q.a)*Math.sign(q.sp),Math.cos(q.a)*Math.sign(q.sp))}});
WD.plaatsen={SWANS};
